<script lang="ts">
import type { Snippet } from 'svelte';
import { untrack, tick, onMount, onDestroy } from 'svelte';
import type { SideNavigationContract } from '@unofficial-krds/contracts';
import { owned, control, resetField, ignoredKey } from './catalog-state.svelte.js';
let p: SideNavigationContract  = $props();
const uid=$props.id();let root=$state<HTMLElement>();
function ancestors(items:typeof p.items,id:string|undefined):string[]{for(const item of items){if(item.id===id)return[];const rest=item.children?ancestors(item.children,id):[];if(item.children?.some(child=>child.id===id)||rest.length)return[item.id,...rest];}return[];}
const expanded=control<readonly string[]>(()=>p.expandedIds,untrack(()=>p.defaultExpandedIds),untrack(()=>ancestors(p.items,p.currentId)),ids=>p.onExpandedChange?.({ids}));function pathTo(items:typeof p.items,id:string|undefined):typeof p.items{for(const item of items){if(item.id===id)return[item];const rest=item.children?pathTo(item.children,id):[];if(rest.length)return[item,...rest];}return[];}
let context=$state<string|null>(untrack(()=>{const path=pathTo(p.items,p.currentId);return path.length>2?path.at(-3)?.id??null:null;}));
const contextPath=$derived(pathTo(p.items,context??undefined));const contextNode=$derived(contextPath.at(-1));const visibleItems=$derived(contextNode?.children??p.items);
async function toggle(id:string,level:number){const closing=expanded.value.includes(id);expanded.request(closing?expanded.value.filter(x=>x!==id):[...expanded.value,id]);await tick();if(!closing&&level===2&&expanded.value.includes(id)){context=pathTo(p.items,id).at(-2)?.id??null;await tick();[...root?.querySelectorAll<HTMLButtonElement>('[aria-controls]')??[]].find(node=>node.getAttribute('aria-controls')===`${uid}-${id}`)?.focus();}}
async function back(){const previous=context;context=contextPath.at(-2)?.id??null;await tick();[...root?.querySelectorAll<HTMLButtonElement>('[aria-controls]')??[]].find(node=>node.getAttribute('aria-controls')===`${uid}-${previous}`)?.focus();}
$effect.pre(()=>{const ids=expanded.value;if(context&&!ids.includes(context)){const previous=context,hadFocus=root?.contains(document.activeElement);context=null;if(hadFocus)void tick().then(()=>[...root?.querySelectorAll<HTMLButtonElement>('[aria-controls]')??[]].find(node=>node.getAttribute('aria-controls')===`${uid}-${previous}`)?.focus());}});

$effect.pre(()=>{const ids=expanded.value;if(!root)return;const node=[...root.querySelectorAll<HTMLElement>('[data-branch]')].find(node=>!ids.includes(node.dataset.branch!)&&!node.hidden&&node.contains(document.activeElement));if(node){const id=node.id;void tick().then(()=>{if(node.hidden)[...root?.querySelectorAll<HTMLButtonElement>('[aria-controls]')??[]].find(trigger=>trigger.getAttribute('aria-controls')===id)?.focus();});}});

</script>
<nav bind:this={root} aria-label={p.title?undefined:'사이드 메뉴'} aria-labelledby={p.title?`${uid}-title`:undefined} {...owned('side-navigation','root',p.currentId&&'current',expanded.value.length?'expanded':'collapsed')}>{#if p.title}<h2 id={`${uid}-title`} {...owned('side-navigation','title')}>{p.title}</h2>{/if}{#if contextNode}<div {...owned('side-navigation','header')}><button type="button" onclick={back}>{contextNode.label} 상위 메뉴</button><span>{contextNode.label}</span></div>{/if}{#if p.parentLink}<a href={p.parentLink.href} {...owned('side-navigation','parent-link')}>{p.parentLink.label}</a>{/if}{#snippet list(items:typeof p.items,level:number)}<ul {...owned('side-navigation',level===1?'list':'submenu',level>1&&'expanded')}>{#each items as item(item.id)}<li {...owned('side-navigation','item',item.id===p.currentId&&'current',item.children&&(expanded.value.includes(item.id)?'expanded':'collapsed'))}>{#if item.href}<a href={item.href} aria-current={item.id===p.currentId?'page':undefined} {...owned('side-navigation','link',item.id===p.currentId&&'current')}>{item.label}</a>{:else if !item.children}<span>{item.label}</span>{/if}{#if item.children}<button type="button" aria-label={item.href?`${item.label} 하위 메뉴`:item.children?.some(child=>child.children)?`${item.label} ${expanded.value.includes(item.id)?'접기':'펼치기'}`:item.label} aria-expanded={expanded.value.includes(item.id)} aria-controls={`${uid}-${item.id}`} {...owned('side-navigation','trigger',expanded.value.includes(item.id)?'expanded':'collapsed')} onclick={()=>toggle(item.id,level)}>{item.href?'하위 메뉴':item.label}</button><div data-branch={item.id} hidden={!expanded.value.includes(item.id)} id={`${uid}-${item.id}`}>{#if level<2}{@render list(item.children,level+1)}{/if}</div>{/if}</li>{/each}</ul>{/snippet}{@render list(visibleItems,1)}</nav>
